#!/usr/bin/env bash
# Hyper Player player/input/scanning consolidated follow-up. Run from existing repo root.
# Usage: bash hyper_player_player_followup.sh --check|--apply|--verify
# Offline, no sudo, no network, no commit/push/build, no Android changes.
set -euo pipefail
if ! command -v python3 >/dev/null 2>&1; then
  printf '%s\n' 'Python 3 is required. No files changed.' >&2
  exit 1
fi
python3 - "$@" <<'HYPER_CONSOLIDATED_PYTHON'
